mapper.select:
SELECT 
FROM review_item

    AND status = #{status}
    AND subject_id = #{subjectId}

ORDER BY next_review_date IS NULL, next_review_date, id

mapper.update:
UPDATE review_item
SET status = 'ARCHIVED', scheduled_date = NULL, version = version + 1
WHERE id = #{id} AND version = #{version}

mapper.select:
SELECT COALESCE(SUM(estimated_minutes), 0)
FROM review_item
WHERE status = 'SCHEDULED' AND scheduled_date = #{date}
